// ============================================================================
// RC testrunner – Deye Remote Control (registers 1100+), accuzijde
// Ingang:  msg.topic = T0 | T1 | T2 | T3 | T4a | T4b | T4c | T5a | T5b | T5c | T6
//                      | STOP | tick | log | clear
// Uitgang 1: HA service calls (select.select_option / number.set_value)
// Uitgang 2: resultaten + log (debug / bestand)
// Elke write wordt via de HA global cache teruggelezen en gecontroleerd.
// Configuratie: dubbelklik het tabblad → Environment variables.
// ============================================================================
const E = (k, d) => { const v = env.get(k); return (v === undefined || v === null || v === '') ? d : v; };
const N = (k, d) => { const v = Number(E(k, d)); return Number.isFinite(v) ? v : d; };

const CFG = {
  ent: {                                                    // RC-entiteiten (zie mysensors.py)
    mode:  E('RC_ENT_MODE',      'select.deye_rc_mode'),          // 1100
    wd:    E('RC_ENT_WATCHDOG',  'number.deye_rc_watchdog'),      // 1101
    side:  E('RC_ENT_SIDE',      'select.deye_rc_side'),          // 1104
    bmode: E('RC_ENT_BATT_MODE', 'select.deye_rc_battery_mode'),  // 1105
    power: E('RC_ENT_POWER',     'number.deye_rc_battery_power'), // 1109  (+ = ontladen, - = laden)
    soc:   E('RC_ENT_SOC',       'number.deye_rc_soc'),           // 1110
  },
  meas: {                                                   // metingen; pShunt/pGrid optioneel (leeg = overslaan)
    pBatt:  E('ENT_BATT_POWER',  'sensor.deye_battery_power'),
    soc:    E('ENT_BATT_SOC',    'sensor.deye_battery_soc'),
    pGrid:  E('ENT_GRID_POWER',  ''),
    pShunt: E('ENT_SHUNT_POWER', ''),
  },
  battSign:  N('BATT_POWER_SIGN', 1),     // 1 als je accusensor + = ontladen geeft, anders -1
  shuntSign: N('SHUNT_POWER_SIGN', -1),   // idem voor een shunt (Victron SmartShunt: - = ontladen → -1)
  dcl:       E('DCL_ENTITY', ''),         // optioneel: number-entiteit voor de BMS-ontlaadstroomgrens (T6 automatisch)
  dclTestA:  N('DCL_TEST_A', 10),
  readbackMs: N('READBACK_S', 8) * 1000,  // wachten na write voor read-back (add-on pollt elke ~5 s)
  sampleMs: 5000,
  maxAbsW:  N('SAFETY_MAX_W', 1500),      // veiligheidsstop: |accuvermogen| boven dit terwijl een test loopt
  wPerPct:  N('W_PER_PCT', 120),          // nominaal omvormervermogen / 100
  keepalive: E('KEEPALIVE_VIA', 'watchdog'), // na T4: 'watchdog' | 'power' | 'mode'
  prefix:   E('STATE_PREFIX', 'rc'),      // om een draaiende remote executor te herkennen
  timeScale: N('TEST_TIME_SCALE', 1),     // alleen voor offline testen
};
const OPT = {
  on:     E('RC_OPT_ON', 'On'),
  off:    E('RC_OPT_OFF', 'Off'),
  accu:   E('RC_OPT_SIDE_BATT', 'Battery'),
  pwr:    E('RC_OPT_POWER', 'Power'),
  pwrSoc: E('RC_OPT_POWER_SOC', 'Power+SOC'),
};

// ---------------------------------------------------------------- helpers
function haStates() {
  const ha = global.get('homeassistant');
  if (!ha) return {};
  const srv = ha.homeAssistant || Object.values(ha)[0];
  return (srv && srv.states) || {};
}
function st(id) { if (!id) return undefined; const s = haStates()[id]; return s ? s.state : undefined; }
function num(id) { const v = parseFloat(st(id)); return Number.isFinite(v) ? v : null; }
function signed(id, sign) { const v = num(id); return v === null ? null : Math.round(v * sign); }
function now() { return Date.now(); }
function secSince(t) { return Math.round((now() - t) / 1000 / CFG.timeScale); }
function avg(a) { const v = a.filter(x => x !== null && x !== undefined); return v.length ? Math.round(v.reduce((s, x) => s + x, 0) / v.length) : null; }
function sleep(ms) { return new Promise(r => setTimeout(r, ms * CFG.timeScale)); }

function log(txt, extra) {
  const L = flow.get('rc_log') || [];
  L.push(Object.assign({ t: new Date().toLocaleTimeString('nl-NL'), txt }, extra || {}));
  while (L.length > 600) L.shift();
  flow.set('rc_log', L);
  node.warn('[RC] ' + txt);
}
function result(test, obj) {
  const R = flow.get('rc_results') || {};
  R[test] = Object.assign({ tijd: new Date().toLocaleString('nl-NL') }, obj);
  flow.set('rc_results', R);
  log(`RESULTAAT ${test}: ${JSON.stringify(obj)}`);
}
function svc(id, value) {
  const domain = id.split('.')[0];
  const isSel = domain === 'select';
  const service = isSel ? 'select_option' : 'set_value';
  return { payload: {
    action: `${domain}.${service}`, domain, service,
    target: { entity_id: [id] },
    data: isSel ? { option: String(value) } : { value: Number(value) },
  } };
}
function check(my) { if (context.get('runId') !== my) throw new Error('gestopt'); }

async function write(id, value, my) {
  check(my);
  node.send([svc(id, value), null]);
  log(`schrijf ${id} = ${value}`);
  await sleep(CFG.readbackMs);
  check(my);
  const got = st(id);
  const g = parseFloat(got), v = Number(value);
  const ok = id.startsWith('select.') ? got === String(value)
           : id === CFG.ent.wd && st(CFG.ent.mode) === OPT.on
             ? (g <= v && g >= v - 20)          // 1101 telt af zodra remote aan staat
             : Math.abs(g - v) < 0.051;
  log(`   read-back: ${got} ${ok ? 'OK' : '<< AFWIJKING'}`);
  if (!ok) throw new Error(`read-back ${id}: verwacht ${value}, kreeg ${got}`);
}

function sample() {
  return { mode: st(CFG.ent.mode), rc: num(CFG.ent.power),
           pBatt: signed(CFG.meas.pBatt, CFG.battSign),
           pShunt: CFG.meas.pShunt ? signed(CFG.meas.pShunt, CFG.shuntSign) : null,
           pGrid: CFG.meas.pGrid ? num(CFG.meas.pGrid) : null,
           soc: num(CFG.meas.soc) };
}
function fmt(s) {
  return `mode ${s.mode} | rc ${s.rc}% | accu ${s.pBatt} W`
    + (CFG.meas.pShunt ? ` | shunt ${s.pShunt} W` : '')
    + (CFG.meas.pGrid ? ` | net ${s.pGrid} W` : '')
    + ` | SOC ${s.soc}%`;
}
function guard(s) {
  if (s.mode === OPT.on && s.pBatt !== null && Math.abs(s.pBatt) > CFG.maxAbsW)
    throw new Error(`VEILIGHEIDSSTOP: |accu| ${s.pBatt} W > ${CFG.maxAbsW} W`);
}

// Observeer 'sec' seconden; tOn = moment van inschakelen (voor terugval-tijd).
async function observe(sec, my, tOn, every = 1) {
  const end = now() + sec * 1000 * CFG.timeScale;
  const S = []; let offAt = null, i = 0;
  while (now() < end) {
    check(my);
    const s = sample(); S.push(s); guard(s);
    if (offAt === null && tOn && s.mode === OPT.off) offAt = secSince(tOn);
    if (i++ % every === 0) log(`  t+${tOn ? secSince(tOn) : '-'}s  ${fmt(s)}`);
    await sleep(CFG.sampleMs);
  }
  return { S, offAt };
}

let kaToggle = false;
async function keepalive(my, wdBase, power) {
  kaToggle = !kaToggle;
  if (CFG.keepalive === 'power') return write(CFG.ent.power, power, my);
  if (CFG.keepalive === 'mode')  return write(CFG.ent.mode, OPT.on, my);
  return write(CFG.ent.wd, kaToggle ? wdBase + 1 : wdBase, my);   // andere waarde -> zeker een write
}

async function enable(my, { bmode = OPT.pwr, power = 0, wd = 120, soc = null }) {
  if (st(CFG.ent.mode) !== OPT.off) throw new Error(`1100 staat niet op '${OPT.off}' (${st(CFG.ent.mode)}) – eerst STOP`);
  await write(CFG.ent.side, OPT.accu, my);        // 1104 vóór 1100: nooit in AC-modus aan
  await write(CFG.ent.bmode, bmode, my);
  if (soc !== null) await write(CFG.ent.soc, soc, my);
  await write(CFG.ent.power, power, my);
  await write(CFG.ent.wd, wd, my);                // watchdog vlak vóór aanzetten
  const tOn = now();
  await write(CFG.ent.mode, OPT.on, my);
  return tOn;
}

async function safeOff() {
  if (st(CFG.ent.mode) === undefined) { log('uit: RC-entiteiten niet gevonden, niets geschreven'); return; }
  node.send([svc(CFG.ent.mode, OPT.off), null]);
  await sleep(3000);
  node.send([svc(CFG.ent.power, 0), null]);
  await sleep(CFG.readbackMs);
  const ok = st(CFG.ent.mode) === OPT.off && Math.abs(num(CFG.ent.power) || 0) < 0.051;
  log(`uit: 1100=${st(CFG.ent.mode)}, 1109=${st(CFG.ent.power)} ${ok ? 'OK' : '<< CONTROLEER HANDMATIG'}`);
}

function precheck() {
  const ids = [...Object.values(CFG.ent), CFG.meas.pBatt, CFG.meas.soc, CFG.meas.pGrid, CFG.meas.pShunt].filter(Boolean);
  const missing = ids.filter(id => st(id) === undefined);
  if (missing.length) throw new Error('entiteit(en) niet gevonden, pas de tab-variabelen aan: ' + missing.join(', '));
  // Een actieve remote executor zou de tests direct overschrijven
  const rs = global.get(`${CFG.prefix}_state`);
  if (rs && rs.enabled && !rs.dry_run && now() - (rs.ts || 0) < 60000)
    throw new Error('de remote executor staat AAN (live) – zet hem eerst UIT');
}

// ---------------------------------------------------------------- tests
const TESTS = {
  async T0() {   // alleen lezen
    const out = {};
    for (const [k, id] of Object.entries({ ...CFG.ent, ...CFG.meas })) if (id) out[k] = st(id);
    result('T0', out);
  },

  async T1(my) {   // watchdog-terugval met vermogen 0
    const tOn = await enable(my, { power: 0, wd: 60 });
    const { S, offAt } = await observe(100, my, tOn);
    result('T1', { watchdog_s: 60, terugval_na_s: offAt,
      ok: offAt !== null && offAt >= 45 && offAt <= 85,
      accu_gem_W_tijdens_aan: avg(S.filter(s => s.mode === OPT.on).map(s => s.pBatt)) });
  },

  async T2(my) { await signTest(my, 5, 'T2'); },
  async T3(my) { await signTest(my, 10, 'T3'); },

  async T4a(my) { await kaTest(my, 'a', () => write(CFG.ent.wd, 61, my)); },
  async T4b(my) { await kaTest(my, 'b', () => write(CFG.ent.power, 0.1, my)); },
  async T4c(my) { await kaTest(my, 'c', () => write(CFG.ent.mode, OPT.on, my)); },

  async T5a(my) {   // ontladen tot SOC−3 (vlak bij het doel knijpt de Deye af)
    const soc = Math.round(num(CFG.meas.soc));
    await socTest(my, 'T5a', 5, soc - 3, s => s.soc <= soc - 3, s => s.soc < soc - 4);
  },
  async T5b(my) {   // laden tot SOC+1
    const soc = Math.round(num(CFG.meas.soc));
    await socTest(my, 'T5b', -5, soc + 1, s => s.soc >= soc + 1, s => s.soc > soc + 2);
  },
  async T5c(my) {   // tegenstrijdig: laden gevraagd, doel onder SOC → hoort niets te doen
    const soc = Math.round(num(CFG.meas.soc));
    const base = avg((await observe(15, my, null)).S.map(s => s.pBatt));
    const tOn = await enable(my, { bmode: OPT.pwrSoc, power: -5, soc: soc - 5, wd: 120 });
    const { S } = await observe(40, my, tOn);
    const a = avg(S.slice(2).map(s => s.pBatt));
    result('T5c', { voor_W: base, tijdens_W: a, verwacht: 'geen geforceerd laden (accu ~0 W, huis uit het net)' });
  },

  async T6(my) {   // BMS-limiet wint van remote-setpoint
    let orig = null;
    if (CFG.dcl) { orig = num(CFG.dcl); await write(CFG.dcl, CFG.dclTestA, my); }
    else { log(`LET OP: zet de ontlaadstroomgrens van je BMS nu handmatig op ~${CFG.dclTestA} A (test start over 20 s)`); await sleep(20000); }
    try {
      const tOn = await enable(my, { power: 10, wd: 120 });
      const { S } = await observe(45, my, tOn);
      const a = avg(S.slice(2).map(s => s.pBatt));
      result('T6', { gevraagd_W: 10 * CFG.wPerPct, gemeten_W: a,
        verwacht: `begrensd op ~${CFG.dclTestA} A × accuspanning` });
    } finally {
      if (CFG.dcl && orig !== null) { node.send([svc(CFG.dcl, orig), null]); log(`DCL terug naar ${orig}`); }
      else log('Vergeet de ontlaadstroomgrens niet terug te zetten!');
    }
  },
};

async function signTest(my, pct, name) {
  const tOn = await enable(my, { power: pct, wd: 120 });
  const plus = await observe(30, my, tOn);
  await write(CFG.ent.power, -pct, my);
  const min = await observe(30, my, tOn);
  const aP = avg(plus.S.slice(2).map(s => s.pBatt)), aM = avg(min.S.slice(2).map(s => s.pBatt));
  const out = { gevraagd_W: pct * CFG.wPerPct, plus_accu_W: aP, min_accu_W: aM,
    W_per_pct: aP !== null && aM !== null ? Math.round((aP - aM) / (2 * pct)) : null,
    teken: aP > 0 && aM < 0 ? '+ = ontladen (zoals verwacht)' : 'AFWIJKEND – bekijk log en BATT_POWER_SIGN' };
  if (CFG.meas.pShunt) {
    out.plus_shunt_W = avg(plus.S.slice(2).map(s => s.pShunt));
    out.min_shunt_W = avg(min.S.slice(2).map(s => s.pShunt));
  }
  result(name, out);
}

async function kaTest(my, v, act) {
  const tOn = await enable(my, { power: 0, wd: 60 });
  const a = await observe(40, my, tOn);
  log(`keepalive-variant ${v} op t+${secSince(tOn)}s`);
  await act();
  const b = await observe(55, my, tOn);
  const offAt = a.offAt ?? b.offAt;
  result('T4' + v, { variant: { a: '1101 herschrijven', b: '1109 herschrijven', c: '1100 herschrijven' }[v],
    terugval_na_s: offAt, verlengd: offAt === null || offAt > 85 });
}

async function socTest(my, name, pct, target, reached, overshoot) {
  const wd = 120;
  const tOn = await enable(my, { bmode: OPT.pwrSoc, power: pct, soc: target, wd });
  const end = now() + 30 * 60000 * CFG.timeScale;
  let lastKa = now(), stable = 0, i = 0, s;
  while (now() < end) {
    check(my);
    s = sample(); guard(s);
    if (i++ % 6 === 0) log(`  t+${secSince(tOn)}s  ${fmt(s)}`);
    if (s.mode === OPT.off) throw new Error('remote viel onverwacht uit (keepalive werkt niet? zie T4)');
    if (overshoot(s)) { result(name, { doel: target, soc: s.soc, ok: false, fout: 'doorgeschoten' }); return; }
    stable = reached(s) && s.pBatt !== null && Math.abs(s.pBatt) < 100 ? stable + 1 : 0;
    if (stable >= 3) { result(name, { doel: target, soc: s.soc, gestopt_na_s: secSince(tOn), ok: true }); return; }
    if (now() - lastKa > 60000 * CFG.timeScale) { await keepalive(my, wd, pct); lastKa = now(); }
    await sleep(CFG.sampleMs);
  }
  result(name, { doel: target, soc: s && s.soc, ok: false, fout: 'doel niet binnen 30 min' });
}

// ---------------------------------------------------------------- dispatcher
const topic = String(msg.topic || '');

if (topic === 'log') {
  return [null, { payload: { resultaten: flow.get('rc_results') || {}, log: flow.get('rc_log') || [] } }];
}
if (topic === 'clear') { flow.set('rc_log', []); flow.set('rc_results', {}); node.status({}); return null; }

if (topic === 'STOP') {
  context.set('runId', -1);
  log('STOP gedrukt');
  safeOff().then(() => node.status({ fill: 'red', shape: 'ring', text: 'gestopt' }));
  return null;
}

if (topic === 'tick') {   // statusregel; veiligheidsstop alleen tijdens een test (niet ingrijpen op een draaiende executor)
  const s = sample();
  if (!context.get('busy')) {
    node.status({ fill: s.mode === OPT.on ? 'yellow' : 'grey', shape: 'dot',
      text: `${s.mode || '?'} | rc ${s.rc}% | accu ${s.pBatt} W | SOC ${s.soc}%` });
    return null;
  }
  if (s.mode === OPT.on && s.pBatt !== null && Math.abs(s.pBatt) > CFG.maxAbsW) {
    context.set('runId', -1);
    log(`VEILIGHEIDSSTOP (tick): accu ${s.pBatt} W`);
    safeOff();
  }
  return null;
}

if (!TESTS[topic]) { node.warn('onbekende test: ' + topic); return null; }
if (context.get('busy')) { node.warn('er loopt al een test – eerst STOP of wachten'); return null; }

const my = now();
context.set('runId', my);
context.set('busy', true);
node.status({ fill: 'blue', shape: 'dot', text: `${topic} loopt…` });
log(`===== start ${topic} =====`);

(async () => {
  let failed = false, started = false;
  try { precheck(); started = true; await TESTS[topic](my); }
  catch (e) { failed = true; log(`AFGEBROKEN: ${e.message}`); }
  finally {
    if (topic !== 'T0' && started) await safeOff();
    context.set('busy', false);
    node.status({ fill: failed ? 'red' : 'green', shape: 'dot', text: `${topic} ${failed ? 'afgebroken' : 'klaar'}` });
    log(`===== einde ${topic} =====`);
  }
})();
return null;
